-- Staging-only migration 218: active-version race guard and standard-hours propagation.
begin;set local lock_timeout='10s';set local statement_timeout='180s';select pg_advisory_xact_lock(hashtextextended('pdc-staging-migration-218-active-rule-hours',0));select public.pdc_monitor_staging_guard();do $guard$ begin if not public.pdc_monitor_staging_guard() or not exists(select 1 from public.pdc_staging_environment_sentinel where singleton and project_ref='cdsmnqxtyyoeoznmbidd') or to_regclass('public.pdc_production_environment_sentinel') is not null or not exists(select 1 from supabase_migrations.schema_migrations where version='217' and name='supervised_correction_evidence_and_admin_telegram_enrollment') or exists(select 1 from supabase_migrations.schema_migrations where version~'^[0-9]+$' and version::integer>217) or exists(select 1 from supabase_migrations.schema_migrations where version='218') then raise exception 'PDC_218_STAGING_OR_LEDGER_MISMATCH' using errcode='55000';end if;end $guard$;
create or replace function public.read_pdc_supervised_learning_rule(p_scope jsonb) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$declare s jsonb:=public.pdc_supervised_monitor_scope_213();r jsonb;v public.pdc_supervised_rule_versions%rowtype;begin if not coalesce((s->>'ok')::boolean,false) then return public.navision_backend_response(false,'forbidden');end if;r:=public.review_pdc_supervised_email_line_213(null,nullif(p_scope->>'operation_code',''),p_scope->>'operation_description',p_scope->>'current_mapping');if not coalesce((r->>'ok')::boolean,false) or r->>'code'<>'deterministic_match' then return public.navision_backend_response(true,'active_lessons',jsonb_build_object('matched',false,'rule',null));end if;select * into v from public.pdc_supervised_rule_versions where version_id=(r->'data'->>'version_id')::uuid and state='active' and effective_from<=clock_timestamp();if not found then return public.navision_backend_response(true,'active_lessons',jsonb_build_object('matched',false,'rule',null));end if;return public.navision_backend_response(true,'active_lessons',jsonb_build_object('matched',true,'rule',jsonb_build_object('lesson_id',v.version_id,'version',v.version_no,'target_mapping',v.work_key,'estimated_hours',v.estimated_hours,'pricing',case when v.cost_ex_gst is null then null else jsonb_build_object('cost_ex_gst',to_char(v.cost_ex_gst,'FM999999990.00'),'sell_ex_gst',to_char(v.sell_ex_gst,'FM999999990.00'),'gst_percent',to_char(v.gst_percent,'FM990.00'),'currency',v.currency) end)));end$$;
create or replace function public.apply_pdc_supervised_learning_rule(p_scope jsonb,p_lesson_id uuid,p_expected_version integer,p_resolution jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$declare s jsonb:=public.pdc_supervised_monitor_scope_213();a uuid;e text;v public.pdc_supervised_rule_versions%rowtype;begin if not coalesce((s->>'ok')::boolean,false) then return public.navision_backend_response(false,'forbidden');end if;a=(s->'data'->>'actor_id')::uuid;e=s->'data'->>'actor_email';select rv.* into v from public.pdc_supervised_rule_versions rv join public.pdc_supervised_rule_families f on f.family_id=rv.family_id where rv.version_id=p_lesson_id and rv.version_no=p_expected_version and rv.state='active' and rv.effective_from<=clock_timestamp() and f.active and f.current_version_id=rv.version_id for share of rv,f;if not found then return public.navision_backend_response(false,'conflict');end if;if p_resolution->>'work_key' is distinct from v.work_key or (p_resolution ? 'estimated_hours' and nullif(p_resolution->>'estimated_hours','')::numeric is distinct from v.estimated_hours) then return public.navision_backend_response(false,'conflict');end if;insert into public.pdc_supervised_monitor_applications(rule_version_id,operation_code,source_description,display_description,source_work_key,applied_work_key,scope,resolution,actor_id,actor_email) values(v.version_id,nullif(p_scope->>'operation_code',''),p_scope->>'operation_description',p_resolution->>'display_description',p_scope->>'current_mapping',v.work_key,p_scope,p_resolution,a,e);return public.navision_backend_response(true,'lesson_activated',jsonb_build_object('work_key',v.work_key,'estimated_hours',v.estimated_hours,'version_id',v.version_id,'version_no',v.version_no,'display_description',p_resolution->>'display_description'));end$$;
revoke all on function public.read_pdc_supervised_learning_rule(jsonb),public.apply_pdc_supervised_learning_rule(jsonb,uuid,integer,jsonb) from public,anon,authenticated,service_role;grant execute on function public.read_pdc_supervised_learning_rule(jsonb),public.apply_pdc_supervised_learning_rule(jsonb,uuid,integer,jsonb) to authenticated;insert into supabase_migrations.schema_migrations(version,name,statements) values('218','supervised_active_version_and_hours_guard',array['Monitor read returns standard hours only from exact active effective rule','Monitor application re-locks active current family version and rejects stale/superseded versions','Monitor resolution must agree with server-owned mapping and hours']);notify pgrst,'reload schema';commit;
